// Real REST/database regressions for event preparation and role boundaries.
function task_row($id) { global $wpdb;return $wpdb->get_row($wpdb->prepare('SELECT * FROM '.CCS::table('tasks').' WHERE id=%d',$id),ARRAY_A); }
function task_payload($id,$extra=[]) {
    $row=task_row($id);$data=array_intersect_key($row,array_flip(['occurrence_id','department_id','team_id','title','description','assigned_id','status','version']));
    $data['due_at']=substr(str_replace(' ','T',$row['due_at']),0,16);
    return array_merge($data,['action'=>'task_save','id'=>$id],$extra);
}
